/* @autogenerated */
import { isAuthenticated } from '@shared/context/authorization-access/guards/is-authenticated.guards';
import { mainRoutes } from './main.routes';

describe('mainRoutes', () => {
  const routes = mainRoutes({} as any, {} as any);

  it('has one route per listed entity', () => {
    expect(routes.length).toBe(33);
    expect(new Set(routes.map((route) => route.path)).size).toBe(routes.length);
  });

  it('labels every route and only opens it to authenticated users', () => {
    routes.forEach((route) => {
      expect(route.data?.['label']).toBeTruthy();
      expect(route.canActivate).toEqual([isAuthenticated]);
    });
  });

  it('lazy loads the list route module of each entity', async () => {
    for (const route of routes) {
      expect(typeof (await (route.loadChildren as any)())).toBe('function');
    }
  });
});
